quests[30379] = { id = 30379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Gina", progress = "Don't just stand there gawking. Spit it out.", completion = "Oh my, this is a flawless jewel!\n\nIf you keep giving me gifts like these, I may have to retire early!" }
quests[30380] = { id = 30380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Gina", progress = "It's busy at the market today. What can I do for you?", completion = "Oh, what a lovely apple! These sweet fruits are quite the treat around here." }
