quests[30382] = { id = 30382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Ella", progress = "It's a lovely day out, don't you think?", completion = "Oh, thank you. This beautiful feather is just lovely." }
quests[30383] = { id = 30383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Ella", progress = "Hmm? Oh hello. How are you today?", completion = "Oh my, these are quite rare. Thank you for giving it to me." }
quests[30384] = { id = 30384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Them!", description = "Horde sunwalkers! We saw one of their scouts patrolling by the oubliette not long before you arrived.\n\nI don't know how he got here but I can guarantee you he isn't alone. They never are.\n\nKill the sunwalker scout before he reports our position.", completion = "Sunwalkers are not to be trusted. They are the most militant branch of the tauren armies within the horde.\n\nThank you for your help in this, {name}. Please accept this token as a reward.", objectives = "Kill the Sunwalker Scout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30385] = { id = 30385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting Sun Garrison", description = "I offer you my heartfelt appreciation for your aid. Anji awaits you in the Setting Sun Garrison to the west.\n\nMay the day favor you, young {class}.", completion = "Welcome. Che send you?", objectives = "Speak to Anji Autumnlight at the Setting Sun Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30386] = { id = 30386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Ella", progress = "A good day to you, neighbor.", completion = "Oh my, Shrimp Dumplings? My favorite!\n\nThank you." }
quests[30387] = { id = 30387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Gina", progress = "Better to have many customers than none at all. How can I help you?", completion = "What an interesting little figurine. It's quite lovely. Thank you, dear." }
quests[30388] = { id = 30388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Gina", progress = "What have you got there, neighbor?", completion = "Such a pretty feather would fetch a nice price at market, but I'm not selling this one. Thank you for the gift." }
quests[30389] = { id = 30389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Gina", progress = "Hello {name}. Are you getting to know everyone in town?", completion = "Oh wonderful! You've brought me a Marsh Lily.\n\nHow did you know that these are my favorite?" }
quests[30390] = { id = 30390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Gina", progress = "I've been on my feet all day. You'd be surprised how busy this place gets.", completion = "Bringing food to me on the busiest market day? What a sweetheart you are!" }
quests[30391] = { id = 30391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Old Hillpaw", progress = "I got my own share of troubles at my farm. I don't need any of yours.", completion = "Oh, for me? Well, I guess that's mighty nice of you." }
quests[30392] = { id = 30392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Old Hillpaw", progress = "Dang monkeys been at my farm again. Sure puts me in a foul mood.", completion = "Well ain't that sweet of ya. Hmph." }
quests[30393] = { id = 30393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Old Hillpaw", progress = "Whaddaya want today, {race}?", completion = "Hmph, well that is mighty fine of you to think of me like that.\n\nThank ye." }
quests[30394] = { id = 30394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Old Hillpaw", progress = "Can't an old man get some peace and quiet around here?", completion = "...\n\nMy son, Tai...he used to collect these as a little boy.\n\nWhen his mother died, I told him they were messages from her, fallen from the heavens.\n\n<Old Hillpaw falls into a quiet silence.>" }
quests[30395] = { id = 30395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Old Hillpaw", progress = "Got a harvest coming up and my back's been giving me trouble again. Oh well, we all have to make do around here.", completion = "Oh, these flowers are quite rare.\n\nYou know that these are considered lucky? Maybe my harvest will go well after all. Thank you." }
quests[30396] = { id = 30396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Old Hillpaw", progress = "My wife used to make the most delicious braised turtle in four counties! I miss that woman.", completion = "I haven't had this dish since my wife died. Somehow, she must have sent you to me.\n\nThank you, {race}." }
quests[30397] = { id = 30397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Chee Chee", progress = "What you want?", completion = "Pretty stone! You silly for giving away. Oh well, mine now!\n\nThanks, {race}!" }
quests[30398] = { id = 30398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Chee Chee", progress = "Me not same as mountain monkeys. You get that straight.", completion = "For me? Red apple? So shiny! So juicy! Thanks, boss!" }
quests[30399] = { id = 30399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Chee Chee", progress = "Chee Chee was first hozen Tiller. If I could do it, so could you.", completion = "Ooh, very old, very valuable. Me like kitties. Got one from girl Ella." }
quests[30400] = { id = 30400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Chee Chee", progress = "Ookin' mountain hozen! They not know how hard little Chee Chee workin'. Bad monkeys!", completion = "Oh my. You know what this is? A frikfrak! Frikfrak for chief only!\n\nWhich mean...you must think me is chief? We boss buddy now, {name}." }
quests[30401] = { id = 30401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Chee Chee", progress = "Little Chee Chee lived here all my life. This is my home.", completion = "Oh! Pretty flower! No takebacks boss, okay? Thank you, bye!" }
quests[30402] = { id = 30402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Chee Chee", progress = "Chee Chee work in fields all day, so tired!", completion = "Oh, Valley Stir Fry. Thanks!" }
quests[30403] = { id = 30403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Sho", progress = "Yes, {class}. What can I do for you?", completion = "For me? Why thank you." }
