quests[30430] = { id = 30430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Tina", progress = "You know, it's hard work looking this good all the time.", completion = "Why this is just lovely! Thank you so much, {name}." }
