quests[30432] = { id = 30432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Tina", progress = "How are things going over at the farm?", completion = "Oh, this will bring me much luck! Thank you, {name}." }
quests[30433] = { id = 30433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Tina", progress = "Please say hello to Farmer Yoon for me.", completion = "Oh this is my favorite dish! Yum!" }
quests[30434] = { id = 30434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Shard for Jogu", progress = "Spare a copper for a drink?", completion = "Oh, a pretty stone! I will look at this while I'm drinking." }
quests[30435] = { id = 30435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lovely Apple for Jogu", progress = "Buy a jinyu a drink?", completion = "Hey, this is my favorite food! Thanks, {name}." }
quests[30436] = { id = 30436, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jade Cat for Jogu", progress = "It's hard work you know, interpreting all these visions.", completion = "Thanks." }
quests[30437] = { id = 30437, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Blue Feather for Jogu", progress = "Tomorrow's crop will be... oh, I can't see it yet. I need something to drink, first.", completion = "A nice blue feather for me? Thanks, {race}." }
quests[30438] = { id = 30438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Marsh Lily for Jogu", progress = "The watersh shay that I will have great fortune today.", completion = "The watersh were right! Thish flower will bring me luck." }
quests[30439] = { id = 30439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dish for Jogu", progress = "You know what goes with a good drink? A good meal.", completion = "Nothing like a delicious cold brew, and some Sauteed Carrots to wash it down." }
quests[30442] = { id = 30442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blanche's Boomer Brew", description = "Brew Blanche's Boomer Brew by Protecting the Brewkegs.", objectives = "Help create the Boomer Brew. If the Brewkegs catch on fire, fix them!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30443] = { id = 30443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Walking on Sunwalkers", description = "The tauren!\n\nI refuse to let those flea bitten beasts claim the Pools of Youth for the Horde. None of their races have earned the right to immortality. They are by nature a series of short lived mortals who lack the humility and knowledge of how to properly support a long lived society.\n\nThey have infiltrators hunting for the pool. Kill those infiltrators before they find it. Their numbers are small so it shouldn't be that hard to cripple their eyes and ears.", objectives = "Kill 3 Sunwalker Infiltrators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30444] = { id = 30444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Reprieve", description = "We've been granted a brief respite from the mogu attacks as they attempt to recoup near the Five Sisters to our north. I would like you to see to it that they not be granted a similar reprieve.\n\nShow no mercy.", completion = "That should keep them off balance for a while. Thanks.", objectives = "Kill 8 Shao-Tien mogu near the Five Sisters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30445] = { id = 30445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waters of Youth", completion = "He... he shouldn't have done that! He shouldn't have paid for my mistake!", objectives = "Give Vaeldrin's message to Lyalia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30449] = { id = 30449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Crane Deck", description = "Now that you have gathered all of the Crane cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a Crane deck!   Congratulations!", completion = "So you have put together a Crane deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Crane Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30450] = { id = 30450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Ox Deck", description = "Now that you have gathered all of the Ox cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a Ox deck!   Congratulations!", completion = "So you have put together a Ox deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Ox Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30451] = { id = 30451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Serpent Deck", description = "Now that you have gathered all of the Serpent cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a Serpent deck!   Congratulations!", completion = "So you have put together a Serpent deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Serpent Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30452] = { id = 30452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Tiger Deck", description = "Now that you have gathered all of the Tiger cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", progress = "I see that you have managed to complete a Tiger deck!   Congratulations!", completion = "So you have put together a Tiger deck.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", objectives = "Return the Tiger Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30453] = { id = 30453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Binan Village Intro Event Tracking Event" }
quests[30454] = { id = 30454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Alliance Tracking Quest" }
quests[30455] = { id = 30455, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Horde Tracking Quest" }
quests[30457] = { id = 30457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call Out Their Leader", description = "Clearly, you are a hero come to aid us.\n\nSlay the Bataari Tribe in the Kun-Lai Pass to the northwest until the Bataari Fire-Warrior is angered enough to appear.  Dispatch him.", progress = "If the war leader of the yaungol is slain, surely our village will be saved and the refugees will be able to return to their farms.", completion = "We are delivered! I was right about you, {class}.", objectives = "Slay 10 Bataari Tribe Members in the Kun-Lai Pass until the Bataari Fire-Warrior appears. Then kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30458] = { id = 30458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scouts Return", description = "{name}, your friends have returned from their scouting mission. They need to see you immediately.\n\nI'm afraid...\n\nWell, I'd better say no more. You will see for yourself.", sourceObjective = "Speak to Rell Nightwind at the Glassfin Village in the Jade Forest.", sourceObjectiveStatus = "unverified-source-field" }
quests[30459] = { id = 30459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All of the Arrows", description = "As soon as their reinforcements arrive, the yaungol are going to overrun our position here. If they do that, the village will be lost.\n\nWould you be willing to retrieve as many arrows off the battlefield as you can carry? I have a plan that just might save us with your help.", progress = "How many arrows do you have?", completion = "Thank you, {name}. You've saved our defensive line here.\n\nThis next attack wouldn't have been possible without you.", objectives = "Collect 12 Arrows for Commander Hsieh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30460] = { id = 30460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hit Medicine", description = "Our warriors are fighting to keep the yaungol at bay in the Kun-Lai Pass to the northwest.\n\nTake this liniment.  It is a powerful medicine that has been passed down in my family over the generations.\n\nUse the dit da jow to heal the injured warriors if you do not have healing powers of your own to use on them.", completion = "You have my thanks, {name}. You have shown great honor through your actions.\n\nI hope that my family's dit da jow was of some use to you.", objectives = "Use the Dit Da Jow or your own healing to aid 8 Injured Binan Warriors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30461] = { id = 30461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Wilds", description = "Deep in the wilds rests the Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here.\n\nThe temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", completion = "I see... So the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Bastion, I have to implore you to help us deal with them here.", objectives = "Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30462] = { id = 30462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Wilds", description = "Deep in the wilds rests the  Temple of the Red Crane, home of the great Chi-Ji and his most devout followers. I suspect they'll know something about what happened here.\n\nThe temple is located on the southern coast of the wilds, where the Krasarang River meets the sea.", completion = "I see... So the sha have seeped out as far as the province already, have they?\n\nWell, I hate to break it to you, but the temple is also overrun with sha. Those of us who haven't been killed or... possessed, or whatever, are fleeing for our very lives.\n\nIf you defeated the sha at Zhu's Bastion, I have to implore you to help us deal with them here.", objectives = "Locate Koro Mistwalker near the Temple of the Red Crane at the southern end of Krasarang River.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30464] = { id = 30464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going West", description = "Leza now walks with the ancestors of this strange land. I must look now to the living.\n\nKor has led a group of our scouts west deeper into the jungle.\n\nTrack him down and lend what aid you can to him. We will join you as quickly as we are able.", completion = "{name}! Well timed!\n\nWe were laying an ambush for the Alliance in the ruins west of here when the mogu ambushed us. They are using mage portals to call in reinforcements.", objectives = "Travel to Dawnchaser Retreat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30465] = { id = 30465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Going on the Offensive", description = "Ha! So my father just wasted twenty years of our lives on a fool's errand!\n\nI'm taking charge.\n\nWhen Tyrande sent us here she was very specific that we not come back until we find the source of the Light that she saw in her visions. It's obvious now that the Pools of Youth were not it.\n\nWe are pressing westward and could use your help.\n\nMeet us at the Sentinel Basecamp further west when you are ready.", completion = "{name}, well timed as usual. It turns out the mogu know how to use portals as well.", objectives = "Speak with Lyalia at the Sentinel Basecamp in the Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30466] = { id = 30466, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sufficient Motivation", description = "Training these savages has been quite a task, {name}.\n\nFinding ways to motivate them was easy enough; the problem is keeping them motivated.. and focused... and awake.\n\nNow that you're back, you can help me in getting the less disciplined Hozen moving, if you catch my drift. I'll leave the method up to you.", progress = "Are the Hozen ready to deploy?", completion = "Hrmm, I'll be surprised if we can keep these creatures focused enough to employ any tactics at all, {name}.\n\nThey'd better not get in my way when blades begin to fly!", objectives = "Motivate 10 Lazy Hozen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30467] = { id = 30467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "My Son...", description = "My son - can you find my son?\n\nWhen the Jinyu attacked, he ran off in the confusion. I don't know if they've done anything with him, or if he's still alive, even.\n\nNothing else matters if I can't find him. \n\nI'd ask Mei... but something's wrong with her. She seems too... impulsive since the attack. I just can't trust that she'd bring him back safely.", completion = "So horrible... When I saw the killing, I just ran. My father, Mei... are they alive?", objectives = "Find Wu-Peng in the Inkgill Mere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30468] = { id = 30468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Vengeance", description = "<The Swordmistress does not look well. There's a darkness to her eyes uncharacteristic of the pandaren.>\n\nI don't think I've ever been as... as furious as now. What betrayal!\n\nI fought them off when they attacked, killed a few here, but Merchant Shi is too much of a coward to let me go and finish the job!\n\nYou, do it for me. Kill them. Kill them all.", completion = "It is satisfying to hear that our enemies are dead. Perhaps you can use one of my bodyguard's weapons.", objectives = "Kill 15 Enraged Jinyu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30469] = { id = 30469, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repossession", description = "Of course, the first priority is finding my son. But, if we save ourselves only to starve, then what have we accomplished, in the end?\n\nPlease, I need you to recover some of the supplies that the Jinyu took from our caravan.", progress = "Have you found the supplies?", completion = "Thank you... we will eat now, at least.", objectives = "Collect 8 Stolen Supplies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30470] = { id = 30470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Tina", description = "That Tina Mudclaw is in the Halfhill Market today, visiting her sister. She's really nice, but she's really hard to get gifts for!\n\nThere's a little jewel that can be found in the cliffs to the north. It's called a chrysoberyl, and it changes color when you hold it. I'll bet she doesn't have one of THOSE!\n\nLook inside the virmen caves. I bet you'll find one really fast.", progress = "Hey there, {name}! Nice to see you again.", completion = "<Tina holds the gem in her hands, and watches it change from a pale blue to a bright red.>\n\nA chrysoberyl? That's so sweet! Was this Andi's idea?\n\nOf course I already have several... but this one is beautiful, too. I'll add it to the collection.", objectives = "Obtain an Uncut Chrysoberyl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30471] = { id = 30471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Chee Chee", description = "That crazy Chee Chee is actually pretty neat. Mah always said that hozen were nothing but trouble, but... I guess he's just a better hozen then the rest of them.\n\nWe should do something nice for him! Those mountain hozen in the west make some really fancy stir fry, and keep bowls of it inside their little hozen houses.\n\nI bet Chee Chee would love some!", progress = "Mmm?", completion = "For me? Me, Chee Chee?\n\nThis brings Chee Chee back to when Chee Chee was little wikkin' baby. Chee Chee's mama used to make it just like this.", objectives = "Obtain an Authentic Valley Stir Fry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30472] = { id = 30472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Sho", description = "Sho - that girl who lives up in the mountains - is in town today. I saw her walking toward the Halfhill Market.\n\nSuch a long walk... she must be hungry! And I think I know just the thing that she'll like.\n\nThe hozen up on the Skyrange cook a soup out of fish and apples. It sounds gross, I know... but it's awesome. You'll find it near their big, scary totem.", progress = "Oh! Hello, {name}.", completion = "I was famished! How'd you know? Who told you?\n\nAndi, huh? That kid's gonna grow up to be a real heartbreaker someday...", objectives = "Obtain a bowl of Yu-Ping Soup.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30473] = { id = 30473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Fish", description = "That Fish Fellreed is kind of weird. First of all, her name's Fish. That's weird.\n\nOnce you talk to her, though, she's really a nice lady. Did you know that she's an animal lover?\n\nI've got an idea! The Kunzen hozen, in the mountains to the west, make little animal statues and put them in their huts to scare off bad guys. I bet Fish would LOVE something weird like that!", progress = "Hey, {name}! What's up?", completion = "Aww, look at him! He's ADORABLE! With his fuzzy little tail, and his...\n\n<She composes herself.>\n\nI mean, ah... thanks, dude. It's pretty cool.", objectives = "Obtain a Yak Statuette from the inside of a Kunzen hozen hut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30474] = { id = 30474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Ella", description = "That poor Ella. She's so shy! I saw her standing in the Halfhill Market, looking really hungry, but afraid to talk to any of the chefs.\n\nWe should bring her some food! And not any boring food - something special.\n\nThe Kunzen hozen make spicy shrimp dumplings from ingredients they've stolen from our farms. I don't like spicy food, but Ella might!", progress = "Oh, umm... hi.", completion = "You didn't have to do this! I didn't need any... any...\n\n<Ella eyes the dumplings, and her mouth begins to water.>\n\nWell, maybe I was a little hungry. Thanks, {name}. And give my thanks to Andi, as well.", objectives = "Obtain Spicy Shrimp Dumplings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30475] = { id = 30475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Fung", description = "Farmer Fung is pretty mean, and just a little scary. Mah always said that he was one of the best farmers in the valley, though.\n\nI think I know the perfect gift for a mean, kind of scary guy like him.\n\nThere's some big plainshawks that circle the hills to the west of here. You should get one, find a big piece of meat, and then ask Kol Ironpaw to grill it up!", progress = "Harrumph!", completion = "Hey! Where'd you get that? I thought they were out of plainshawk!\n\nAndi asked you to get this for me? Huh. Maybe I underestimated that kid.", objectives = "Obtain a Bloody Plainshawk Leg from a Monstrous Plainshawk, and then bring it to Kol Ironpaw in the Halfhill Market.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30476] = { id = 30476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Old Hillpaw", description = "Old Hillpaw has about a million chickens on his farm... but that's not what he REALLY loves.\n\nI saw. He collects blue feathers.\n\nI don't realy know where to get a blue feather around here, but I do know where to find some blue pearls!\n\nCheck the oysters in Cattail Lake to the northwest. I'm sure a blue pearl will look nice with his feather collection!", progress = "{name}! You startled me.", completion = "Well would you look at that! I'll have to keep this somewhere that the chickens can't get to.\n\nDid Andi tell you to get this for me? Funny kid, that one.", objectives = "Find a Blue Freshwater Pearl.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30477] = { id = 30477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Haohan", description = "Haohan Mudclaw is the big boss of the Tillers union and the richest guy in the Valley! He's been nice to let me stay here, so I want to do something nice for him.\n\nHe likes expensive stuff, like ruby shards, but I don't have a lot of money, so I need to get him something else.\n\nI know! I've seen a great big fish in Cattail Lake! We should get one of its teeth as a gift!", progress = "Need something, {class}?", completion = "Well, would you look at that! You don't see a tooth like THAT everyday.\n\nYou been hunting sharks, {class}?\n\nThank you, {name}. And send my thanks to Andi, as well.", objectives = "Obtain an Enormous Cattail Grouper Tooth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30478] = { id = 30478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Jogu", description = "Sometimes I feel sad for Jogu. He's the only jinyu around, and I don't think he has any friends. Other than his smelly bottle, of course.\n\nYou know what? I've got an idea. Farmer Yoon has a basket of craneberries inside his house, and a few apples as well. I'm sure you could bring them to the stillmaster in the Halfhill Market and get him to brew something special for Jogu.", progress = "Hmm?", completion = "<Jogu takes a long swig from the hooch.>\n\nThat'sh it! I've got a new favorite drink. An' it'sh this one!\n\nYou know what, {name}? You're alright. I mean it, man!", objectives = "Obtain 8 of Yoon's Apples and 50 of Yoon's Craneberries, then bring them to Bobo Ironpaw to brew into Apple-Berry Hooch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30479] = { id = 30479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift For Gina", description = "Have you seen Gina Mudclaw, the market girl? She has it all - looks, brains, and nice big tummy. Could you deliver a gift for me?\n\nI wanted to pick some orchids that grow on top of the big hills to the west, but I can't climb that high. Could you pick a few and bring them to Gina?\n\nOh, and when you see her... tell her I said \"hi\".", progress = "Hey there!", completion = "These are beautiful! Did you get these for me?\n\nAhh... so they're from Andi, are they? I think I know somebody who's getting a kiss on the forehead later this afternoon...", objectives = "Obtain a Goldenfire Orchid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30480] = { id = 30480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual", description = "From the moment I first rose from the river, I knew I was destined to be Waterspeaker.\n\nI was taught many rituals, and have performed all of them, save one.\n\nThere was one, an extremely ancient one, that we were told to call upon if our people ever turned against us. \n\nThis must have happened in our people's distant past, because we haven't needed to use it in our village's memory.\n\nI suppose now is the time to do so.", progress = "That... was not what I expected.", completion = "I see now that this ritual rips whatever was controlling the minds of these creatures from them. I now know what we must do.", objectives = "Speak with Waterspeaker Gorai, and then complete the Ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30481] = { id = 30481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carved in Stone", description = "You see the shiny stones in the walls? Rook wants some. The mogu been collecting them, so they have some to take too maybe.\n\nIf you find stones, you please bring them to Rook? Rook will be your friend.", progress = "You find stones for Rook? Please?", completion = "So many!  And so shiny! You did real good!\n\nThank you, little friend. Rook like you a lot.", objectives = "Collect 12 Guo-Lai Runestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30482] = { id = 30482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Soul-Gatherer", description = "A single large mogu performing a ritual on the lake caught your attention while you were killing the other mogu in the area. It seems unwise to let his ritual complete.", progress = "<He looks at you expectantly.>", completion = "<As you hand the beads to He, his smile suggests that he understands perfectly what they symbolize. He nods approvingly.>", objectives = "Kill Shadowmaster Sydow and recover the beads from his corpse.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30484] = { id = 30484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gauging Our Progress", description = "The time for war is at hand, {name}!\n\nWe've been training these natives non-stop since you left, and I believe they're as good as they're going to get.\n\nSee for yourself. Check in with the others and return with your findings.\n\nWe must rely on our enemy being somehow... even less prepared.", progress = "How is our combat training coming along?", completion = "At least they're confident.\n\nThat might count for something.", objectives = "Check in with Shademaster Kiryn, Rivett Clutchpop, Shokia, and Riko.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30485] = { id = 30485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Piece of the Puzzle", description = "These hozen are behaving most unnaturally, {name}. Marching in formation? In armor?\n\nThis troubles me. We must discuss it at another time, however. I have come to ask for your assistance.\n\nThe ancient fresco, where last we spoke, is nearly unveiled. I am certain that it holds ancient wisdom - knowledge that the emperor wanted us to remember.\n\nMy meditations alone may not be enough to discern its meaning. Please, take this heirloom to the shrine of my ancestors. I shall require their assistance.", completion = "<Lorewalker Cho shudders, in spite of himself.>\n\nThe legends... they're true!", objectives = "Use Cho's Heirloom at Cho's Family Shrine on Serpent's Overlook.\n\nSpeak with Mishi for transportation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30486] = { id = 30486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jade Dragon Phased Terrain Tracking" }
quests[30487] = { id = 30487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Comin' Round the Mountain", description = "The mountain pass is very dangerous. You need much luck to survive. Nephew Bentnail will show you the way.\n\nPerhaps today is a lucky day to travel though. Wind blows from the east; this is good sign. Grummles always travel best when east wind blows.\n\nClimb in the cart when you are ready to leave.", progress = "You must be very lucky to survive the pass!", completion = "You've arrived just in time, {class}! I was starting to think I would die up here!", objectives = "Escort the cart and guides safely up Neverest Mountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30488] = { id = 30488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Muskpaw", description = "What the heck are you supposed to be? |5{class}? Never heard of one of them. You here to help or to steal my yaks?\n\nLook, if yer' insistin' on helpin' out, go find my boy. He got himself grabbed by a bunch of sprites and probably doesn't even know we lost the ranch.\n\nThey dragged him off to Pranksters' Hollow south east of here. Go rescue him an' I'll see about giving you a reward of some sort.", completion = "Thank you for the save, stranger!", objectives = "Find Muskpaw Jr. in Pranksters' Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30489] = { id = 30489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Needle Scent", description = "Say, if you really are here to help, I could use me some needles off them sprites in Pranksters' Hollow.\n\nThe grummles don't believe in luck they can't smell. They'll pay better for yaks that have that fresh needle scent.", progress = "Mmm. Nothing like the fresh scent of needle.", completion = "You just earned me a handsome bonus. Getting those needles is a pain in the paw but worth it when we take our yaks to market. Here, for your troubles.", objectives = "Gather 100 Pungent Sprite Needles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30490] = { id = 30490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yakity Yak", description = "Yaungols! They come through here taking what they want and destroying whatever's left.\n\nI can't have these thugs destroy the last pieces of the Yak Wash here. It's all my boy and I have left.\n\nHead over to our old ranch and dish out some pain on them yaungols. I bet if you kill enough of them they'll think twice before attacking anything in this area.", objectives = "Kill 9 Burilgi Despoilers at the Muskpaw Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30491] = { id = 30491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "At the Yak Wash", description = "Look, my father is crazy. I love him, but he's crazy.\n\nThese yaungol managed to completely obliterate our ranch and scattered our yaks every which way.\n\nIf I know my father though, he's going to try to go head to head with the yaungol to get the yaks back.\n\nCan you help us round up some of the yaks so my father doesn't do anything stupid?\n\nJust ride them over to the Yak Wash so we can clean them up and sell them to the grummles.", progress = "The grummles always insist they have better luck with cleaned yaks.\n\nAs long as they pay more I'm not going to argue. We need the gold. Now more than ever.", completion = "Well done, stranger! Hopefully we'll be able to cash these in and recoup some of the damages the yaungol inflicted.", objectives = "Bring 6 Escaped Yaks to the Wash Entrance at Lao & Son's Yak Wash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30492] = { id = 30492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back in Yak", description = "I wasn't lying about your reward. Here, take these washed yaks to the grummle caravan master Eightcoins.\n\nYou can find him at the Grummle Bazaar west of here. He'll credit us and give you a delivery fee.\n\nHe may be short, but he is our biggest customer.\n\nReturn to me if you lose the yaks. More often than not they just come right back here anyway. Once they've been cleaned that is.", progress = "And what have we here?", completion = "Ah! I can smell the luck from here. The Muskpaws always have good yaks for sale.", objectives = "Bring the Washed Yaks to Lucky Eightcoins at the Grummle Bazaar in Kun-Lai Summit. Return to Muskpaw Jr. if you lose your yaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30495] = { id = 30495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Love's Labor", description = "Can I trouble you for another favor?\n\nWe're way behind schedule, and this jade shipment is the last we need to finish the great statue.\n\nI've got my hands full, so could you run this ore over to the other foremen?\n\nHistorian Dinh, Surveyor Sawa, and Kitemaster Shoku can all be found around the base of the statue. Taskmaster Emi is directing production at the top of the statue.\n\nWe're on a deadline, so make sure you do it fast! Time's a wasting!", progress = "Did you deliver the jade in time?", completion = "What, done already? You're quite the runner, {class}. You ever thought about making a living out of this?", objectives = "Deliver the jade to Historian Dinh, Surveyor Sawa, Kitemaster Shoku, and Taskmaster Emi.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30496] = { id = 30496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Waterspeaker's Staff", description = "There is great dissent in Inkgill, {race}. Elder Shai Hu drank the sha-corrupted waters of the mere, and forced the others to do the same. When I protested, Orachi of the town guard confiscated my ritual staff and banished me.\n\nNow, I am not only an exile, I am unable to speak with the waters that once gave me guidance!\n\nI am not a fighter. But if you are, perhaps you can recover my staff from Orachi? He is in town to our north.", progress = "Have you found the staff?", completion = "Good. Now we have some hope of redeeming this situation.", objectives = "Recover Waterspeaker Gorai's Stolen Inkgill Ritual Staff from Orachi in Inkgill Mere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30498] = { id = 30498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Back Here!", description = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume.\n\nI was made to understand that your presence was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", completion = "Welcome back, {name}. I trust your journey has been insightful, particularly in regards to the layout of the land. There is still much to do before we march into battle.", objectives = "Report to Admiral Taylor in Pearlfin Village.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30499] = { id = 30499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Back Here!", description = "Oh, before I forget, I have something I was asked to deliver to you. A letter from one of your companions, I assume.\n\nI was made to understand that your presence was urgently required, so I took the liberty of arranging your passage.\n\nSpeak to Ginsa Arroweye just south of here when you're ready. She has a kite waiting.", completion = "Throm-Ka, {name}!\n\nI hope you were able to gather useful information while on your journey through the forest.\n\nOur preperations are almost complete, but your help is needed.", objectives = "Return to General Nazgrim at Grookin Hill.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30500] = { id = 30500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Residual Fallout", description = "Pandaria is a mystical land, traveler.\n\nIt bears repeating that some of its secrets remain hidden, even to Lorewalkers.\n\nSealing those fissures did not mend what has been broken. If the legends are true, it will take much more to release this land from the grasp of the Sha.\n\nThe aggression of that battle awakened a host of living negative emotions. What you see here is likely the first of many such manifestations.\n\nFor now, we can only try to diminish their presence here.", progress = "This, it seems, is only the tip of the iceberg, {name}.", completion = "This is terrible...\n\nWe must find a way to undo what has been done here.", objectives = "Destroy 10 Sha Echoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30501] = { id = 30501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gossip Accept Quest Test Case" }
quests[30502] = { id = 30502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaded Heart", description = "The more powerful remnants of that horrible manifestation may be too much for you to handle on your own, {name}.\n\nI fear I'd be of little help in terms of actual combat, but I can suggest a solution.\n\nThe great jade statue was soon to become a living serpent - one of our revered celestials. Its construction imbued it with special powers that may sufficiently weaken these adversaries.", progress = "Do you have the jade, {name}?", completion = "<Cho looks at you despondently.>\n\nThis jade was meant for... so much more.", objectives = "Use Celestial Jade Chunks to defeat 6 Sha Remnants.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30504] = { id = 30504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emergency Response", description = "Your companions have made themselves at home in our land, and brought with them a dangerous conflict.\n\nThe full extent of their destruction here we cannot yet know. Already it is... unspeakable.\n\nNevertheless, to forsake your friends out of spite would be against our way. Any that yet live are doubtlessly wounded and in desperate need of care.\n\nThese fireworks were to celebrate the statue's completion. Use them near your companions to signal Mishi, and she will bear them off to safety.", completion = "My thoughts will be with your fallen companions, traveler.\n\nMay their wounds mend well.", objectives = "Use Cho's Fireworks near General Nazgrim, Shademaster Kiryn, Shokia, and Rivett Clutchpop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30506] = { id = 30506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has requested your presence.", completion = "{name}, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway.", objectives = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30507] = { id = 30507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way.\n\nHe has requested your presence.", completion = "{name}, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway.", objectives = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30508] = { id = 30508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor has Awakened", description = "It would seem that your Admiral Taylor has awakened from his injuries. He and his people are upstairs.\n\nHe has requested your presence.", completion = "{name}, is that you? I can't believe we survived the destruction of the Jade Serpent.\n\nSome of us anyway.", objectives = "Speak with Admiral Taylor at Binan Village in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30509] = { id = 30509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house back in Binan Village.\n\nHe has requested your presence.", completion = "Where have you been, {name}? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they.", objectives = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30510] = { id = 30510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs in the apothecary's house across the way.\n\nHe has requested your presence.", completion = "Where have you been, {name}? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they.", objectives = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30511] = { id = 30511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Nazgrim has Awakened", description = "It would seem that your General Nazgrim has awakened from his injuries. He and his people are upstairs.\n\nHe has requested your presence.", completion = "Where have you been, {name}? Nevermind. As you can see, we survived the battle at the Jade Serpent.\n\nUnfortunately, so did... they.", objectives = "Speak with General Nazgrim at Binan Village in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30512] = { id = 30512, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westwind Rest", description = "<Admiral Taylor winces in pain.>\n\nJade Forest was a disaster. \n\nAnduin's gone. We lost some good people. We didn't stop the Horde from advancing into the continent. \n\nBut I think I've found a way to get the locals on our side. You just helped fight off some of these \"yaungol\", no?\n\nI hear yaungol sacked Westwind Rest, a local village. We've been told that two groups of survivors have camped out along the road west out of town.\n\nWe help them out, maybe they'll consider siding with the Allliance.", progress = "I will not rest until our people are returned and this village rebuilt.", completion = "Well... we are alive, and that is better than we could have hoped for without your help.\n\nBut, if this is truly to become a base of operations for you, and if we are to join your Alliance, there is one more thing you must do to guarantee our security.", objectives = "Speak with Farmhand Bo and Elder Tsulan in the Yaungol Advance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30513] = { id = 30513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eastwind Rest", description = "I am injured, but we can't stop here.\n\nThe hozen were... unreliable. The pandaren would be much better allies.\n\nYou have seen the refugees in this village, and heard of the yaungol invasion, no?\n\nWell, we've heard from the locals that Eastwind Rest, a nearby village, was destroyed by the Yaungol.\n\nApparently some survivors have gathered along the road out of town.\n\nGo. Take the road west. Gather the survivors. \n\nWe'll help them rebuild. Then, they will see the advantage of joining the Horde!", progress = "I will not rest until our people are returned and this village rebuilt.", completion = "Well... we are alive, and that is better than we could have hoped for without your help.\n\nBut, if this is truly to become a base of operations for you, and if we are to join your Horde, there is one more thing you must do to guarantee our security.", objectives = "Speak with Farmhand Ko and Elder Shiao in Kun Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30514] = { id = 30514, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge Accepted", description = "The yaungol have always been a difficult, proud people, but never this violent or aggressive. \n\nI do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.", completion = "You did it! At the very least, we have justice, and safety, though in the process we have lost so much.\n\nRegardless, it has been decided. We will join the Alliance, and with your help, rebuild this village.", objectives = "Set the Yaungol Banner ablaze to summon Ur-Bataar, and then defeat him in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30515] = { id = 30515, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge Accepted", description = "The yaungol have always been a difficult, proud people, but never this violent or aggressive. \n\nI do not know what has prompted this change in their behavior, but we don't have time to find out, now. We fear for our lives and livelihoods as long as Ur-Bataar, leader of the Bataari yaungol, lives.\n\nGo, set the banner in his camp ablaze to challenge him, and then defeat him in battle. Only then will we be secure.", progress = "As long as Ur-Bataar lives, we cannot have peace.", completion = "You did it! At the very least, we have justice, and safety, though in the process we have lost so much.\n\nRegardless, it has been decided. We will join the Horde, and with your help, rebuild this village.", objectives = "Set the Yaungol Banner at Fire Camp Bataar ablaze to summon Ur-Bataar, and then defeat him in combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30516] = { id = 30516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm I: A Little Problem", description = "So you need to whack some wily weeds?\n\nNo problem, neighbor! Only thing is, I'm running low on weed killer.\n\nI make my own concoction - very potent, totally organic and good for the earth. Plants love it! Well... except for those pesky weeds. They hate the stuff!\n\nIf you bring me some Spideroot from the terraces just west of us, I'll make a fresh batch and go down to Yoon's farm myself.\n\nI would gather some myself but... well... I hate spiders. You'll see what I mean.", progress = "How did the root gathering go?", completion = "Well what do we have here? You harvested enough to last me a while.\n\nMany thanks!", objectives = "Gather 6 Spideroot for Gai Lan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30517] = { id = 30517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmer Fung's Vote I: Yak Attack", description = "The next voting member on the Tiller's council is Farmer Fung, and it's easy to see why.\n\nThat man's vegetables are the biggest in the valley! I only hope that someday I can grow pumpkins as big as his.\n\nIf we hope to join the Tillers, he would be the next person to convince.", completion = "Oh? You're with that new farmer in town, aren't you?", objectives = "Speak to Farmer Fung at The Heartland or the Halfhill Market in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30518] = { id = 30518, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmer Fung's Vote II: On the Loose", description = "You want my vote for Farmer Yoon? Ha! You're joking, right?\n\nListen, I'm not going to vote for some citypaw with no lick a' knowledge about farming the earth.\n\nIt would be an embarrassment to farm alongside you or that Yoon shmuck.\n\nNow let me deal with my own problems. Some devil let my prize yaks loose, and now they're running wild northwest of Halfhill.\n\nIf I could just get my yaks back, then maybe I'd be able to sleep at night.", completion = "<Farmer Fung stares at you with his jaw on the floor.>\n\nI... I can't believe... YOU recovered all of my prized shagskins!\n\nDo you... do you know what this means to me?\n\nMy family's only been good at two things - raising enormous vegetables and raising yaks.\n\nThe shagskins you see are the result of generations of work.\n\nYou have saved my family's legacy, {name}.", objectives = "Return 5 Escaped Shagskins to Farmer Fung's yak pen at the very north end of the Verdant Belt.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30519] = { id = 30519, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nana's Vote I: Nana's Secret Recipe", description = "The next vote we'll need is from Nana Mudclaw. She's Haohan's grandmother, and she's been a Tiller longer than you and I have been alive!\n\nShe's still working at the Tillers building in Halfhill. Why don't you pay her a visit?", completion = "Yes, Nana Mudclaw... that is me. I may be old, dear, but I haven't lost my memory. Old Man Whitewhiskers, on the other hand, is another story.", objectives = "Speak to Nana Mudclaw at Halfhill in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30520] = { id = 30520, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tummy Trouble", description = "I like Farmer Yoon just dandy as a neighbor, but getting my vote is another matter entirely. He does know that my father is the head of the Union, right?\n\nAnyway, I've got bigger problems to worry about. Lotta folks been getting sick from eating bad vegetables.\n\nSince they bought the produce from my market, my reputation is in jeopardy.\n\nNow I've got an idea to cure the stomach rumbles, but it ain't pretty.\n\nIf you'd be willing to... um... hurry things along, I just might be indebted to you.", objectives = "Use Gooseberries to cure sick Halfhill Villagers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30521] = { id = 30521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote I: Bungalow Break-In", description = "This is going to be tough, {name}.\n\nThe last vote we need comes from Haohan Mudclaw, the head of the Tillers Union.\n\nI know he wasn't too keen on us to start, but we've learned so much about farming, I'm sure he'll have a change of heart!\n\nGo speak to him. You can be very convincing, right?", completion = "What do you want?", objectives = "Speak to Haohan Mudclaw at The Heartland or at Halfhill Market in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30522] = { id = 30522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote II: The Real Culprits", description = "What are YOU doing here, citypaw?\n\nLook, I've got my hands full with a break-in at my shed to the west. Some rascals came in the middle of the night and ransacked the place.\n\nI've got missing seeds, broken tools, and eaten inventory to deal with.\n\nI'll just add it to my list of other troubles: a whole wagon of melons stolen, a broken water pump, animals ruining my harvest...\n\nI wish that I could just get to the bottom of all this already!", completion = "Hmmm, I'm sorry to hear that Haohan's up to his neck in trouble. Thank you for bringing me this news. Maybe we can help him out.", objectives = "Investigate 8 Suspicious Footprints.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30523] = { id = 30523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm II: The Broken Wagon", description = "Hey {name}. I've been looking at that wagon every day, day in and day out, since the day I moved in. Quite an eyesore, don't you think?\n\nI heard in town that Fish Fellreed is quite handy with tools. She might be able to fix it up, and then we could turn that patch of land into a plot for farming.\n\nWhy don't you talk to her and see if she'd be willing to do the job?", completion = "You need my help fer somethin'? You came to the right gal!", objectives = "Speak to Fish Fellreed at Cattail Lake or the Halfhill Market in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30524] = { id = 30524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm II: Knock on Wood", description = "Sure! I know just the wagon that you're talkin' about!\n\nI can fix it right up, but I'll need wood.\n\nThere's a whole lot of it down at the bottom of the lake. If you fish it right out - haha, get it? Fish? Oh I just crack myself up sometimes.\n\nAnyway, you bring me here some 'o that wood and then I'll get right to work!", progress = "That lake is plum full o' treasures! You just gotta know what to look for.", completion = "Aww yeah, this wood'll do jus' fine. You did good, {name}.", objectives = "Collect 100 Waxed Planks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30525] = { id = 30525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote III: Pure Poison", description = "All right, {name}. This is our big chance!\n\nMr. Mudclaw's farm is in big trouble. Those mountain hozen are coming down at night, wrecking his crops and eating his hard-earned harvest.\n\nWe've got to get rid of them for good, and I know just how to do it.\n\nBack in the day, my grandpa showed me how to mix a wounding poison to deal with the pests on the farm.\n\nThe virmen warrens to the north hold the key ingredients for my mixture.\n\nDon't look so worried, {name}! I'm pretty sure this is going to work.", progress = "The hozen are going to get a big surprise!", completion = "You got the ingredients? Good work!\n\nNow I just need to make the concoction.", objectives = "Collect 1 Bloodbloom, 1 Cave Lily, 1 Ghostcap, and 1 Violet Lichen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30526] = { id = 30526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost and Lonely", description = "The starving, mangy dog whines piteously and attempts a brief wag of its tail.\n\nIt looks like it could use a good meal right about now.", progress = "A light comes into the dog's eyes. It seems to recognize you.", completion = "The dog perks its ears up at the sight of the juicy steak.\n\nAs soon as you throw it down, the dog starts eating ravenously.", objectives = "Collect 20 Tasty T-Bone from the Skyrange Mushan on the Skyrange in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30527] = { id = 30527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote IV: Melons For Felons", description = "All right, now I happen to know that those mountain hozen love a delicious, sweet melon.\n\nMr. Haohan's last harvest of melons got stolen, so we're going to have to grow some of our own.\n\nOnce we have our harvest, we'll use them to lure the nasty hozen's leader out of its cave!", progress = "Let's make sure we grow some good melons, {name}. Those crafty hozen only like the sweetest melons.", completion = "Wow, {name}! Those are some big melons. Those are hard to grow, and I should know because I've tried! \n\nI don't know how I would run this place without you, {name}.", objectives = "Plant and harvest 4 Striped Melons, then deliver 20 Striped Melons to Farmer Yoon.\n\nStriped Melon Seeds can be purchased from Merchant Greenfield at Halfhill Market. After tilling and tending your plant, you must wait until the next day to harvest ripe Striped Melons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30528] = { id = 30528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haohan's Vote V: Chief Yip-Yip", description = "You ready for the final step of the plan?\n\nThe leader of the Kunzen hozen is a brute by the name of Chief Yip-Yip. It's said that he is nearly impervious to pain.\n\nI've injected the melons with a toxic mixture, so don't try eating them!\n\nOnce you get his attention, throw these melons onto the ground. Yip-Yip won't be able to resist a sweet striped melon.\n\nWhen he takes a bite, he'll be temporarily weakened, and you should find yourself an opening to attack.", completion = "The hozen chief is dead? Our plan worked, {name}!", objectives = "Kill Chief Yip-Yip at Kunzen Cave to the northwest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30529] = { id = 30529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing the Farm III: The Mossy Boulder", description = "Now that we're officially members of the Tillers Union, Mr. Mudclaw said he'd be happy to help us upturn this big ole' rock in the middle of our field.\n\nOnce we clear away that stone, I've got something special planned.\n\nRun down and give him a holler to let him know that we're ready.", completion = "Yoon needs a neighbor to lend a hand, eh? Well I'll be plenty happy to oblige.", objectives = "Speak to Haohan Mudclaw in The Heartland or at Halfhill Market in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30530] = { id = 30530, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Started First Expansion" }
quests[30531] = { id = 30531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Finished First Expansion" }
quests[30532] = { id = 30532, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Started Second Expansion" }
quests[30533] = { id = 30533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Finished Second Expansion" }
quests[30534] = { id = 30534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Second Hand", description = "Despite your best efforts, the work is starting to pile up around here.\n\nPerhaps you could ask one of your best friends if they'd like to help out at Sunsong Ranch.", progress = "It's a sturdy rake.", completion = "The talismans on the shrine tinkle softly in the wind.", objectives = "Speak to one of your best friends and ask them to work on Sunsong Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30535] = { id = 30535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learn and Grow I: Seeds", description = "Well, first things first! I'm going to need lots of help 'round here.\n\nIf we're going to be partners, you've got to learn how to harvest crops, and if you wanna harvest crops you gotta plant seeds!\n\nNow it's my understanding that a mister, uh... Grainfell? No, that wasn't it... Greedfill? That doesn't sound right...\n\nGreenfield! That's his name! He's the man to see for seeds.\n\nGreenfield's got a stall over at Halfhill Market, directly southeast of here - go see him and pick up some vegetable seeds.", progress = "How'd it go, partner? Did you get those seeds from Groanfur?\n\nErr... Greenfield?", completion = "He waved at me! And he gave you the first pack of seeds for free?\n\nWell, what a nice guy!\n\nYou're doing a great job so far. Here's a little... seed money. Hah!", objectives = "Speak with Merchant Greenfield at Halfhill Market and acquire a Packet of Green Cabbage Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30536] = { id = 30536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Weed War Training", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.", objectives = "Listen to Xiao and his companions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30537] = { id = 30537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fizzy Fusion" }
quests[30538] = { id = 30538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fun for the Little Ones" }
quests[30564] = { id = 30564, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Talked to Dog at Farm" }
quests[30565] = { id = 30565, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unexpected Advantage", description = "Things seem to be goin' our way more and more lately, {name}. I was out doin some explorin' when I came upon this little beauty.\n\n<Sully gestures to the ballista to his right.>\n\nProblem is she's one of a set and the other one is still in pieces. I'd have gotten it together by now if those pesky Grimleers hadn't ambushed me and taken some of the gears and bolts.\n\nHey, ye seem to be pretty good at handlin' the natives. Ye wouldn't mind goin' and helpin' ol'Sully out would ye?", progress = "Did ye find my missing gears and bolts?", completion = "Well these aren't as good as she deserves, but it will have to work.\n\n<Sully pats the dismantled ballista.>\n\nI'll get 'er up and runnin' in no time, just ye watch!", objectives = "Retrieve the missing Water-Damaged Gears and Rusty Locking Bolts from the Hozen Ambushers to the East.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30566] = { id = 30566, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Pest Problems Training", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.", objectives = "Listen to Xiao and his companions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30567] = { id = 30567, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blanche's Boomer Brew", description = "Can you smell it in the air? A storm is brewing! And so am I!\n\nMeet me at the hilltop when the storm hits and together we'll whip up a keg of my most famous brew. Can I count on your help?", completion = "None too shabby, my {class} friend! We've saved the monastery and still have half a keg left.\n\nThank you for your help!", objectives = "Complete the \"Brewing Storm\" Scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30568] = { id = 30568, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helping the Cause", description = "Welcome back, {name}! It seems the Jinyu have taken to our training even better than I had hoped. We're in the final stages of our preparations now.\n\nI need someone to go check in with Amber, Bold Karasshi, and Mishka. See if they need any help to complete their training.\n\nYou'll find Karasshi and Mishka here in Pearlfin Village. Amber is training recruits in Slingtail Pits to the northwest.", progress = "Is everyone in order and ready to move?", completion = "Impressive work, {name}. We should be ready to move out shortly. With our allies at our side, there is no way we can be defeated.", objectives = "Check in with Bold Karasshi, Amber Kearnen, and Mishka.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30569] = { id = 30569, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble on the Farmstead", description = "I... I escaped from Farmer Chow's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there and help him out. Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", completion = "You're a sight for sore eyes, {class}.\n\nI'll be glad to help you Alliance fellas out. First though, you need to help me get my farm back.", objectives = "Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30570] = { id = 30570, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble on the Farmstead", description = "I... I escaped from Farmer Chow's, to the southeast of here. It's been taken over by yaungol, but the old man and his wife just won't give it up!\n\nPlease, go there and help him... Maybe if you do, he'll be willing to send some folks back here and help you guys farm up some food for the new town?", completion = "You're a sight for sore eyes, {class}.\n\nI'll be glad to help you Horde fellas out. First though, you need to help me get my farm back.", objectives = "Speak with Farmer Chow at the Chow Farmstead in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30571] = { id = 30571, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Farmhand Freedom", description = "Those Ordo yaungol are working my farmhands to death! It just ain't right.\n\nPlease, {class}, save them before it's too late.", progress = "Look, mister, I don't mean to be telling you your business, but I can still see a lot of my farmhands still out there.", completion = "Now ain't you just the thing?\n\nThough, I guess it's not fair to force these here workers to stay with us, now that we don't have much work for 'em...", objectives = "Free 12 Farmstead Slaves by killing Ordo Overseers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30573] = { id = 30573, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Started Third Expansion" }
quests[30574] = { id = 30574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Finished Third Expansion" }
quests[30575] = { id = 30575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Round 'Em Up", description = "Mobility is going to be key to maintaining our foothold in this new land. Problem is, there's no way to maintain mobility without mounts, and... well, we don't have many of those here, now do we?\n\nThe local yaks seem to make good mounts. At least, the local pandaren say they do. Why don't you go round some up for us?", progress = "It's going to take more yaks than that to get this place back into fightin' condition, {name}, yes it is.", completion = "These yaks will do the trick nicely. Good work, {name}. I'm feeling better about this whole situation already.", objectives = "Round up 3 Wild Plains Yaks and return them to Westwind Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30581] = { id = 30581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... and the Pot, Too!", description = "Sure, I'm willing to help you guys out. But we need to eat, too! I don't even have a pot to cook in! Let alone ingredients to put in it!\n\nHere's a list of the things that I need. Now get!", progress = "Do you have everything from the list?!", completion = "Well there you go. We should be plenty good, now.", objectives = "Collect 12 Root Vegetables and 1 Cast Iron Pot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30582] = { id = 30582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Late Mrs. Muskpaw", description = "This well worn trinket has several markings on it confessing love and adoration from the late Mrs. Muskpaw.\n\nPerhaps Lao would like his wife's trinket back.", progress = "Oh, and what have you there.", completion = "Ya never know how much you can lose until you've lost it. My wife passed a few seasons ago, but I can tell you this is a day when I could use her smile the most.\n\nAt least she doesn't have to see what these yaungol did to her beloved ranch.", objectives = "Bring the Muskpaw Keepsake to Lao Muskpaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30583] = { id = 30583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blue Dwarf Needs Food Badly", description = "Oi!\n\nWe need ta' get us some food, if we're gonna survive here for long!\n\nYe' may not know it, but I'm somethin' of a cook me'self. Why don'tcha go out there and fetch us some meaty bits. I can cook 'em up and feed us for weeks! Or, days, at least.", progress = "Well... ya' got my meat?", completion = "Good work! I'm telliin' ye, these Kun-Lai meaty bits are grade A goodness!", objectives = "Collect 160 Kun-Lai Meaty Bits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30584] = { id = 30584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shocking!", description = "Have you ever had a fresh dojani eel {name}?  No?\n\nWell you have not lived then!  Head north up to the dojani river and fish up a few for us.   Be careful, those eels can zap you if you're not careful!", progress = "Were you able to catch the eels?", completion = "These look like some tasty eels {name}!  I'm sure you will love them!", objectives = "Fish up 7 Dojani Eels from the Dojani River in Krasarang Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30585] = { id = 30585, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Lurks Below", description = "Legend tells of a great beast in the forest to the north.  My son is missing and I fear he may have wandered too near its lair....\n\nHead northwest to Krasari Falls and look for a mysterious whirlpool - this is the key to revealing what is hidden there.  Kill the wretched beast and recover any clues to my son's whereabouts.", progress = "What news of my son?", completion = "My son's ring?  What does this mean?\n\n<Rassan appears thoughtful.>\n\nThe situation is grim, but not without hope.  My son is careless with his belongings, so perhaps he simply threw it into the pool?  Thank you for your help {name}, I will not soon forget this great favor you have done for me.", objectives = "Find an Ancient Fishing Pool at Krasari Falls to the northwest and fish in it to lure the beast out of hiding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30586] = { id = 30586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagged Abalone", description = "Pandaren have been harvesting jagged abalone in this area for generations.  Now it's time for you to learn the ritual.\n\nThe abalone can be found just northeast of here in narsong trench.  Be careful, we have noticed increased shark activity in that area recently.", progress = "Did you see any sharks down there?", completion = "Oh!  Looks like you found plenty of abalone out there.  Great job {name}!", objectives = "Harvest 9 Jagged Abalone Meat from the Jagged Abalone in Narsong Trench to the northeast.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30587] = { id = 30587, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yakity Yak", description = "For now, the yaungol invaders seem content to steal yaks. Surveying the area, however, you notice they could easily move on the Yak Wash at any moment.\n\nThinning their numbers may help show the yaungol that this area is protected.", progress = "Them yak stealing, ranch smashing, bad breath yaungols gotta learn a thing or two about attacking decent folk.", completion = "Well then, I am mighty grateful for you culling some of those yaungols for us.\n\nHopefully your little display of authority will be enough to discourage them from coming over here.", objectives = "Kill 9 Burilgi Despoilers at the Muskpaw Ranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30588] = { id = 30588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishing for a Bruising", description = "The riverblade saurok clan is attacking one of our local fishing expeditions!  They need help right away!\n\nThin those saurok out and help that expedition return safely!", completion = "The expedition is safe.  Thank you {name}.", objectives = "Kill 8 Riverblade Beach Raiders at Anglers Expedition, just west of Anglers Wharf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30589] = { id = 30589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wrecking the Wreck", description = "To dislodge the alliance ship, we need to find our engineer. He parted ways with us when we were escaping the wreckage.\n\nYou should be able to find him somewhere in the western forest. Tell him Korga sent you and he'll get in line to help.", completion = "Korga sent you, eh? Well, I wouldn't mind doing a number on that ship for my own reasons anyway, but it's going to take some work.\n\nGive me a moment to think...", objectives = "Speak to Makael Bay in the Pei-Wu Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30590] = { id = 30590, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handle With Care", description = "We can help you get your ship free, but we'll need more of the explosives we were trying to take back from the Alliance to make it happen.\n\nI ordered the men to grab all the explosives they could before making our escape. If you sift through the wreckage and bodies to our south, there should be some explosive bundles among them, those that didn't already blow up anyway.\n\nGet me enough of them and I think I can put something together for ya.", progress = "You're in one piece. That's a good sign.\n\nDid you get your hands on what I asked for?", completion = "More than enough. I've got the main control panel constructed. We should be ready very soon!", objectives = "Recover 6 Packed Explosive Charges.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30591] = { id = 30591, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preying on the Predators", description = "The forest has become far more dangerous ever since Shen-zin Su began shaking. The tigers are agitated and have begun attacking the refugees, and on occasion, me as well.\n\nIf these injured and weak survivors are to make it to safety here at the hut, we need to help clear the forest for them.", progress = "Grim work. I've lived in peace with these tigers for as long as I can remember.", completion = "These survivors are in your debt, {class}.", objectives = "Kill 9 Pei-Wu Tigers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30592] = { id = 30592, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burlap Trail: To Burlap Waystation", description = "Bad fortune for grummles today. Hozen have begun to ravage! They attack our supply line to the Serpent's Spine.\n\nCan you help? We are not fighters. We are grummles. Good fortune to those who help grummles.\n\nGo with a group of grummles to the Burlap Waystation. Keep them safe. Make sure at least one grummle survives.\n\nGrummles shall reward. Grummles always reward.", progress = "Good fortune to friends of grummles.", completion = "Many thanks and fortune to you, friend of grummles. But the journey to the Serpent's Spine is not safe yet.", objectives = "Protect a group of grummles travelling to the Burlap Waystation. At least one grummle must survive.\n\nIf you lose your grummles, you can search the Burlap Trail or return to One Keg and wait for the next group to leave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30593] = { id = 30593, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deanimate the Reanimated", description = "The admiral's asked me to take care of a major problem, but my specialty's in healing, not fighting!\n\nThe pandaren in the camp here have told me that something is animating the statues to the northeast at Mogujia.\n\nWill you help me out, {name}? We can't afford to have a fight with an army of statues right now.", completion = "Alright! Looks like we won't have a bunch of statues to worry about any more. Good work, {name}!", objectives = "Destroy any 14 Terracotta Warriors or Terracotta Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30594] = { id = 30594, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deanimate the Reanimated", description = "I've got much to do here, {name}. I could use your help.\n\nThere's a place to the northwest. The pandaren here call it Mogujia. Something's causing the statues there to animate, and our pandaren friends here are pretty spooked about it.\n\nIf they're not dealt with soon, we might have a serious problem. We just moved in. It's not like we can afford to fight a war with an army of statues right now.", progress = "Weren't you going to destroy all of those mogu statues so that we don't, you know, get overrun by them?", completion = "Oh, you dealt with the statues? Good work. Here's something for your trouble.", objectives = "Destroy any 14 Terracotta Warriors or Terracotta Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30595] = { id = 30595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Profiting off of the Past", description = "Let me guess, you're here to deal with the mogu statues that are being reanimated. What a coincidence, I'm here to, um... conduct research on the mogu.\n\nI tell you what, if you bring me as many of the mogu relics in there that you can carry, I'll give you a cut. Of the research... funding.", progress = "Where am I going to be able to put all of the relics?", completion = "Wow! I mean, wow! Thank you, {name}!\n\n\n\nNow that you've softened them up, I'm thinking that I might head in. Just a few more relics from around the outskirts. Nothing dangerous.", objectives = "Collect 12 Mogu Relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30596] = { id = 30596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Zandalari Troll?", description = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you.\n\nIt's clear that the threat to Westerly Rest will not end until he's been dealt with.", objectives = "Kill the Zandalari Soulraiser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30597] = { id = 30597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strange Spherical Stone", description = "This beautiful stone clearly has magical potential... at least to one trained in alchemy.  You are certain that with the right herbs native to Pandaria, this stone could become very useful.", objectives = "Infuse the stone with several Golden Lotus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30598] = { id = 30598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Knew Fish Liked Eggs?", description = "Great cranes have been nesting in this area for generations.  The Narsong Spires provide a sheltered area to rear their young.\n\nTheir pristine eggs are revered as bait for catching the silver goby.  Retrieve a crane egg and see if you can catch a goby!", progress = "Did you catch a silver goby?", completion = "The elusive silver goby!  You truly are becoming an angler {name}!", objectives = "Collect a Pristine Egg from the Narsong Spires and use it to catch a Silver Goby.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30599] = { id = 30599, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Monkey Idol", description = "Before, grummles keep hozen from ravaging by bribing with food.\n\nBut now the Broketooth hozen south of here have their big magic idols. The Ook of Dook has trained them to use their idols to get power from sacrifices.\n\nThey are using them to kill grummles!\n\nYou must destroy these idols!\n\nFor every idol, there is a chief. Kill the chief and throw corpse on their altar.", progress = "Hozen are learning that it is most bad fortune to get sacrificed on one's own altar.", completion = "A confident hozen is a dangerous hozen.\n\nThank you for your help, friend of grummles.", objectives = "Use the Corpses of Tak Tak, Dak Dak, and Ko Ko on their respective altars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30600] = { id = 30600, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Pack Left Behind", description = "The Broketooth hozen south of here killed all of my grummles. What is worse, their packages are undelivered.\n\nFortune frowns on a grummlepack undelivered.\n\nPlease, give my grummles peace on the great trail of beyond and bring their grummlepacks to me.\n\nI will see they are delivered.", progress = "Grummles are a simple people. We are made to explore and deliver.", completion = "You are good fortune for grummles.\n\nWhen we are back at a proper camp I must buy you the smelliest, luckiest incense I can find.", objectives = "Recover 8 Grummlepacks from Camp Broketooth or The Deeper.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30601] = { id = 30601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instant Courage", description = "It is very bad fortune to travel mountain paths without a good guide. We grummles make the best guides, but many have run away. They fear the mountain pass now. Many good grummles disappear up there.\n\nGrummles are good at many things, but are not very brave. Maybe with fire lotus incense you can make them brave. Then they will show you the way.", progress = "Did you find the hiding guides?", completion = "Incense works like a charm! Effects will not last long, so you must hurry!", objectives = "Inspire 3 Hiding Guides in Howlingwind Cavern to help you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30602] = { id = 30602, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rabbitsfoot", description = "The Broketooth hozen stole our Rabbitsfoot! He was the grummle with the biggest luckydo.\n\nThis is very bad fortune indeed. Please, {race}, we need our Rabbitsfoot back. We need his good fortune back.\n\nCan you search the Broketooth Outpost for him?", completion = "Look what Broketooths and Knucklethumps did to grummle waystation. Hardly a luckydo to be found.\n\nGrummles had a deal with the hozen. We give them food, and they don't ravage. Whenever they think to ravage, Shado-Pan remind them not to ravage.\n\nBut all of Shado-Pan are away defending the wall now. And the hozen want more food than the grummles have.", objectives = "Rescue Brother Rabbitsfoot from the Broketooth Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30603] = { id = 30603, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Broketooth Ravage", description = "They took my luckydo! Their leader hozen here, Mo Mo, stole my rabbitsfoot.\n\nThis is most bad fortune for grummles. My rabbitsfoot is a big luckydo for grummles everywhere. If hozen learn how to get luck from my rabbitsfoot then all is lost.\n\nPlease can you get it back?", progress = "Grummles named for the luckydo that gives the most fortune to specific grummle. It is most important that hozen not steal a grummle's luck.", completion = "My luckydo! Oh happy day of good fortune! Many thanks!", objectives = "Retrieve Rabbitsfoot's Luckydo from Mo Mo.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30604] = { id = 30604, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking Broketooth", description = "Hozen only ravage when they think their supplies are too few for their number of mouths.\n\nProblem is, hozen always have more mouths than food.\n\nWe have very few grummles these days.\n\nIt is a hard thing to ask, but can you be a friend to grummles, and destroy some of the Broketooth hozen south of here? It is the only way to prevent them from destroying the landscape.", completion = "Thank you, {name}! Hopefully that will slow the Broketooth ravage.", objectives = "Kill 8 Broketooth Chargers and 6 Broketooth Tossers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30605] = { id = 30605, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lucky Yakshoe", completion = "Good fortune for me to be saved by a luckydo like you.\n\nAnd Brother Rabbitsfoot always say I not have good fortune. Bah!", objectives = "Rescue Brother Yakshoe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30606] = { id = 30606, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thumping Knucklethump", description = "The Knucklethump hozen have new chief, the Ook of Dook.\n\nHe sees fear in the west, anger in the south, hatred in the north, and yaungols in the east.\n\nAnd so he sets his hozen to ravage, gathering food and supplies for coming famine.\n\nThey are many Knucklethumps and dangerous.\n\nPlease, Luckydo, can you defeat their fighters?", progress = "It is sad so many hozen must die.", completion = "You are a true luckydo.", objectives = "Slay 8 Knucklethump Smashers or Jibstabbers at Knucklethump Hole.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30607] = { id = 30607, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hozen Love Their Keys", description = "The hozen have a yeti! They call it Old Poot Poot and keep it at the back of their cave.\n\nHozen are normally scared of yeti, but now they feed it grummles.\n\nThey have a Hunter Chief, Cho Cho the Wicked. Can you see if he has a key on him to the yeti shackles?\n\nBad fortune for hozen if a yeti is loose in their fort.", progress = "A luckydo would be wise to never travel near a yeti on a dirty yak.", completion = "Oh wow that looked like one wild ride!", objectives = "Get the Yeti Shackle Key from Cho Cho the Wicked and release Old Poot Poot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30608] = { id = 30608, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Snackrifice", description = "They took my grummles! Hozen don't eat grummles, but yeti do. And the Knucklethumps have a yeti.\n\nPlease rescue my grummles. Cut them down or let them out of cages. Rescue them any way you can.\n\nMany fortunes and rewards if you do this.", completion = "Today is a day of many good and bad fortunes. Bad fortune that hozen stole my grummles. Good fortune that my {race} saves my grummles. Bad fortune that so many hozen must die to learn lesson. Good fortune that humans are luckydos and know how to fight.\n\nGrummles are not fighters. We carry, we explore, and we are content.", objectives = "Rescue 5 Imprisoned Grummles by cutting them down or releasing them from cages.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30609] = { id = 30609, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exit Strategy" }
quests[30610] = { id = 30610, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grummle! Grummle! Grummle!", description = "Now that grummles are rescued, we need to rescue our supplies.\n\nThe Ook of Dook is only chief because he has supplies.\n\nGo to the Dooker Dome area north west of here. Take some grummles with you. Keep them safe and get them near supply crates.\n\nGrummles know what to do from there.\n\nRabbitsfoot and I will meet you there.", progress = "Grummles are good at carrying things.", completion = "Now that hozen king is going to learn why it is bad fortune to cheat grummles.", objectives = "Lead 5 Packless Grummles to Supply Crates near the Dooker Dome.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30611] = { id = 30611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleash The Yeti!", description = "Your yeti ride gave me an idea. The Ook of Dook has a pet yeti he named Chomp Chomp.\n\nHe uses this yeti to scare other hozen in to making him the leader hozen. We need to get rid of that yeti.\n\nGo to Dooker Dome northwest of here and defeat some of the Cagemasters so Chomp Chomp is not tied up as much.\n\nYakshoe and I will meet you there with lots of incense and a dirty yak.", progress = "We found a yak. Did you take out some hozen?", completion = "Ready for the yeti?", objectives = "Kill 4 Cagemasters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30612] = { id = 30612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leader Hozen", description = "The time has come to face the Ook of Dook. We beat him, and the hozen won't have someone telling them to ravage.\n\nHere is the plan: Yakshoe will lead Tassle in to arena and scare away Chomp Chomp.\n\nThen, you sneak in and fight the Ook of Dook while his hozen are distracted by the yeti rampaging through their home.\n\nWe'll meet you back at Kota Basecamp with a big reward. Good fortune to you, friend of grummles.", completion = "The Ook of Dook is dead! Hurray!", objectives = "Enrage Chomp Chomp and then defeat the Ook of Dook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30613] = { id = 30613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armored Carp", description = "Armored Carp are a delicacy around these parts.\n\nUnfortunately we can't fish them up since they snap our hooks with their powerful jaws.  Take this fishing spear and see if you can catch a few for us.", progress = "Any luck with that fishing spear?", completion = "Careful with that carp, {name}.  They have been known to bite fingers off!", objectives = "Use the Fishing Spear to catch 5 Armored Carp in the waters south of Anglers Wharf.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30614] = { id = 30614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oil Stop", description = "When the yaungols came, they began to dig up oil. What is this \"oil\", I wonder? Perhaps it is thing of much undiscovered luck. This I must know.\n\nHere, take this vial, and fill it with yaungol oil from one of their windmills. I will give you many fortunes if you bring me some.", progress = "Yaungols are scary. Yaungols with a luckydo like this \"oil\" are more scary.", completion = "Happy day! Your reward. May these coins bring you good fortune.", objectives = "Fill the Empty Oil Vial at a Yaungol Oil Derrick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30615] = { id = 30615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Zandalari Troll?", description = "While you've been destroying the reanimated mogu statues, the unmistakable accent of a Zandalari troll has been taunting you.\n\nIt's clear that the threat to Westerly Rest will not end until he's been dealt with.", objectives = "Kill the Zandalari Soulraiser.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30616] = { id = 30616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traffic Issues", description = "Yaungols are attacking our Burlap Trail. This is most bad fortune for grummles.\n\nWe use that trail to carry supplies to the Serpent's Spine. Without supplies, the defenders of the wall are in danger.\n\nGrummles are packers and explorers, not fighters. Could you be a luckydo for us and stop the yaungol blockade?", completion = "It is good fortune that a {race} comes to help grummles. Good fortune to friend of grummles.", objectives = "Defeat 8 Fire Camp Ruqin Yaungols.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30617] = { id = 30617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Roadside Assistance", description = "A luckydo remembers to bring incense on a journey in to the mountains. The smellier the luck the better.\n\nCan you journey up the road to One Keg and light the incense you find along the way?\n\nThis will give good fortune to grummles that must travel the road.\n\nBrother Lintpocket can give you many rewards. Speak to him when you arrive.", progress = "The pungent smell of lucky burning burlap in the morning is a big Luckydo.", completion = "Welcome to One Keg! Gateway to Burlap Trail and Mount Neverest.", objectives = "Light 8 Lucky Burlap Incense sticks along the road to One Keg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30618] = { id = 30618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resupplying One Keg", description = "If you're looking for the best supplies in Kun-Lai you've come to the right place! Oh sure, it looks a bit empty. Don't let appearances deceive you..\n\nOh, who am I kidding?! Between the hozen attacks, and the sprites pillaging what few supplies we do get, my stock has dwindled to a dangerous level.\n\nIf you could help me recover some of my supplies I should have enough to contribute to your journey.", progress = "Did you manage to get some of my supplies back?", completion = "Oh thank you, {name}! If I just cut off the nibbled pieces and repair the minor damage, I may still be able to sell these.\n\nOnce your cart is ready to go I'll have the supplies I promised loaded up!", objectives = "Recover 8 Stolen Supplies from Howlingwind Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30619] = { id = 30619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu?! Oh No-gu!", description = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about.\n\nWhere there are animated statues, there are mogu. I don't know if you've seen one before, but if you haven't...\n\nWell, let's just say mogu are bad, bad, news.\n\nWhile you're dealing with whatever else you're doing, you need to get the mogu behind the trouble!", progress = "Did you find him? Is he dead? No? Oh, man. Don't make me worried!", completion = "Oh, thank goodness! You've saved all of our skins, believe me.\n\nYou have no idea how much trouble those guys can stir up.\n\nErr, or, I guess you do, now. Kind of. Almost.\n\nImagine that, but a lot worse, and for a couple thousand years.", objectives = "Kill the Mogujia Soul-Caller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30620] = { id = 30620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mogu?! Oh No-gu!", description = "I know your friends are worried about the animating statues over at Mogujia, but I'll tell you what you should really be worried about.\n\nWhere there are animated statues, there are Mogu. I don't know if you've seen one before, but if you haven't...\n\nWell, let's just say Mogu are bad, bad, news.\n\nWhile you're dealing with whatever else you're doing, you need to get the Mogu behind the trouble!", completion = "Oh, thank goodness! You've saved all of our skins, believe me.\n\nYou have no idea how much trouble those guys can stir up.\n\nErr, or, I guess you do, now. Kind of. Almost.\n\nImagine that, but a lot worse, and for a couple thousand years.", objectives = "Kill the Mogujia Soul-Caller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30621] = { id = 30621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Stole My Luck!", description = "My journeys through Kun-Lai have taught me two things. First, never sneak up on a sleeping yak. Second, having luck on your side is both necessary and hard to come by.\n\nThe grummles believe in carrying a lucky trinket at all times. In my mind, if one trinket can sometimes bring luck, then many trinkets would guarantee it!\n\nAfter arriving in One Keg my lucky trinkets were stolen by those little menace sprites. I'd be truly grateful if you could retrieve them for me.", progress = "Were you able to find my lucky trinkets? One can never have too much good luck.", completion = "Thank you! It appears my trinkets were lucky for you too, {class}. While you were gone I did not gamble and lose my cart.\n\nI would be happy to lend it to you for your journey. Besides, I have some goods to win back from this shady grummle!", objectives = "Return Ji-Lu the Lucky's Lucky Virmen's Foot, Yak Shoe, Four Winds Clover, and Gold Coin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30622] = { id = 30622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Swarm Begins", description = "Without the wall to protect us, we barely stand a chance. If you hadn't gathered so many people to help us, we wouldn't have a prayer.\n\nCheck in with Captain Oakenshield - he should be up near the break in the wall. Kill as many mantid as you can on the way there.\n\nIf we win, we win. If we lose, we go down fighting. For Pandaria!", progress = "Look at the SIZE of that thing...", completion = "My wall... I spent my life atop that wall...", objectives = "Slay 15 Ik'thik Warriors or Ik'thik Infestors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30623] = { id = 30623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mantidote", description = "<Mei motions towards the battlefield.>\n\nYou see those huge mantid commanders out there? They have a strange aura about them. It reminds me of the sadness we saw at Zhu's Watch.\n\nPerhaps... they're under the influence of the sha, too?\n\nI kept Ken-Ken's mask - the one he used to remove the sha from Yi-Mo. I believe that, if we use it on the mantid, we can convince them to turn back.", objectives = "Use Ken-Ken's Mask on 5 Ik'thik Wing Commanders, then defeat the Manifestations of Fear that come out.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30624] = { id = 30624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Does You No Good In The Keg", description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together.\n\nThere's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", objectives = "Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the night elf settlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30625] = { id = 30625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Students No More", description = "Those five students - the ones who were looking for the Hidden Master - they went up to the front lines, alone. I'd send Shado-Pan to aid them, but I haven't got any left.\n\nThere's dangerous creatures up there near the wall. If you find those students, make sure that they haven't fallen to any of them.", completion = "They can't keep fighting like this forever. Those kids are downright heroic, but I don't want them to die as heroes.\n\nIt's time to throw in the towel.", objectives = "Find the martial arts students, then help them defeat an Ik'thik Bloodrager, Egg-Matron, Tendon-Slicer, and Fearmonger.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30626] = { id = 30626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retreat!", description = "I'm going to withdraw what few forces I have. We may have to fall back to the Stormstout Brewery, or even Halfhill. That call is Commander Loon Mai's to make.\n\nYou go ahead. Deliver word to the Commander. My Shado-Pan will be shortly behind.", completion = "I see.\n\nWell, we gave it our all. It's time to evacuate, save lives, and reassess our strategy, before these mantid take over the entire valley.", objectives = "Report to Loon Mai at Stoneplow in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30627] = { id = 30627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Savior of Stoneplow", description = "That commander speaks hastily. He has the weapon he needs to win this battle. He has YOU.\n\n\"But it's too hard,\" you might say.\n\nYou would be wrong. It is not too hard. NOTHING IS TOO HARD.\n\nGo now, {name}. Go, and save Stoneplow!", progress = "All is lost, {name}. Pack up your things. We're headed to Halfhill.", completion = "I can't believe it! You - a foreign-born {race} - have succeeded where the Shado-Pan have failed. You've succeeded where the WALL has failed.\n\nWe may hold this farming village after all.", objectives = "Speak with Miss Fanny at Stoneplow. Then, with her help, defeat the Mantid Colossus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30628] = { id = 30628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gratitude of Stoneplow", description = "One last thing, {name}. Don't worry, it's not another favor. You've killed enough mantid today.\n\nWe recently received a shipment of high-quality armor from Kun-Lai Summit. I was planning to keep them for my men... but I can't think of anybody more deserving than you. You'll find them on the second floor of the inn, here in town.", completion = "Peering inside, you find...", objectives = "Find the Commander's Cache and collect your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30629] = { id = 30629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Player Began Finale", description = "Oh, hello. Are you looking for the owner of this place? Then look to the pandaren up at the top of the stairs. I'm just a visitor... like you.\n\nNow if you'll excuse me, my friends and I trying to decide something. We can talk again afterwards.", objectives = "Listen to Xiao and his companions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30630] = { id = 30630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Vale", description = "Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Matron Vi Vinh at the Shrine of Seven Stars.\n\nShe should be able to settle you in.", sourceObjective = "Speak to Matron Vi Vinh at the Shrine of Seven Stars in the Vale of Eternal Blossoms.", sourceObjectiveStatus = "unverified-source-field" }
quests[30631] = { id = 30631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of Seven Stars", description = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning.\n\nHis blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley.\n\nThe caretakers are settling your people into the city to the southeast. Go and speak to the leaders. Make sure they are safe.", completion = "Good work, {name}. It sounds as though they are getting on quite well at the city.\n\nHowever, in order to ensure their safety, we must be even more vigilant than before.", objectives = "Speak to Jaluu the Generous, Kuru the Light-Hearted, Lucky Lin, and Matron Vi Vinh in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30632] = { id = 30632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Guo-Lai", description = "According to Zhi the Harmonious, the mogu are moving into the Vale from the Ruins of Guo-Lai to the west.\n\nI sent Anji and Kun to investigate the situation, but they have not yet returned.\n\nI need a capable {class} like you to go check on them.", completion = "Leven sent you? I hope you're ready for a fight.", objectives = "Speak to Anji Autumnlight at the Ruins of Guo-Lai in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30633] = { id = 30633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out with the Scouts", description = "We'd been briefed on mogu sightings in the Vale, but the situation is worse than we had anticipated.\n\nScouts are swarming all over the ruins to the northwest, gathering intel and stealing treasures.\n\nYour objective is clear - dispatch of any scouts you see. An army cannot move if we take out its eyes.", completion = "Well done, {race}. That should send a clear message to the mogu - we are not to be trifled with.", objectives = "Kill 8 Shao-Tien Precursor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30634] = { id = 30634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barring Entry", description = "Lao Softfoot and I scouted up the ruins to the north.\n\nIt looks like the mogu are infiltrating the valley through a cave just up the hill, and already they are sending formidable reinforcements through.\n\nThere are too many enemies to take them head on, so you'll have to meet Lao Softfoot at the entrance to the ruins.\n\nHe'll help you sneak in under the cover of stealth. Then, plant this keg of explosives at the mouth of the cave.\n\nThe rest should take care of itself.", completion = "Wonderful, {name}!\n\nYou and He have single-handedly crippled the mogu advance.\n\nThat is called working smarter, not harder.", objectives = "Speak to Lao Softfoot at the entrance to Ruins Rise and follow him up the trail. Then, plant the Explosive Keg at the Ruins Rise Cave Entrance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30635] = { id = 30635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Killing the Quilen", description = "We've taken care of the scout problem for now, but there are still advance mogu forces inside the Guo-Lai Halls down the hill.\n\nUnfortunately, their vicious guard dogs are protecting their operations deeper in the ruins.\n\nGo and dispatch of their beasts. Be on your guard - they can be quite good at blending into their surroundings.", completion = "Good. Those dogs know no mercy, so it's good that you showed them none.", objectives = "Kill 9 Stone Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30636] = { id = 30636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stones of Power", description = "Many thousands of years ago, the rulers of the Vale sought energy from a powerful crystal known as Revelite.\n\nWith this substance, they were able to power cities, factories, and engines of war.\n\nZhi the Harmonious has asked us to collect some crystals and bring them back to the city.\n\nKeep an eye out for them while you are in the ruins.", progress = "Did you find the crystals?", completion = "Mmmhmm. These will do nicely.\n\nI'll have them sent back to camp immediately.", objectives = "Collect 7 Revelite Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30637] = { id = 30637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guo-Lai Halls", description = "As you pass by the great door, you hear sounds from deep inside.\n\nAnji mentioned that advance mogu scouts had been sighted in this area. Perhaps they made their way down to the depths below.\n\nYour senses tingling, you decide to investigate.", completion = "Your instincts were correct, {name}.\n\nIn ancient times, the Guo-Lai Halls were home to powerful treasures.\n\nWe must do everything we can to stop this mogu warlord from accessing those sealed crypts.", objectives = "Investigate the mogu presence in the Guo-Lai Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30638] = { id = 30638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leaving an Opening", description = "This is serious.\n\nKun and I will keep an eye on things here, but you should go to the Golden Pagoda.\n\nGo, swiftly!", completion = "To arms, {name}! I thought we would have more time to set up our defenses, but the mogu are proving to be a deadly and intelligent enemy.\n\nWe've moved the refugees and our supplies into the city behind us.\n\nIt's up to us to protect the front. We must not let the mogu gain a single foothold here in the Vale.", objectives = "Speak to Leven Dawnblade at the Golden Pagoda in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30639] = { id = 30639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Guo-Lai", description = "I just received information from a guard stationed near the Ruins of Guo-Lai that the Shado-Tien leader entered the halls, killing two of my men in the process. They're intent on something inside. We need to stop them.\n\nHe Softfoot has already followed them in. He should be waiting for you at the entrance to the western chambers.\n\nMove quickly, {name}. I don't like the thought that the mogu may be a step ahead of us.", completion = "The Shao-Tien were spotted marching out of the halls with a hundred jade statues. The mogu now have an immense jade army to turn against us, and we've yet to uncover their other goals in the Vale. We are all in danger.\n\nI had thought you and He dead. It's good that I was mistaken on the last part at least. Rest. Recover. There will be much fighting ahead.", objectives = "Meet with He Softfoot in the Guo-Lai Halls and uncover the mogu's purpose in the western chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30640] = { id = 30640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Spear of the Thunder King", description = "I have received some troubling news, {name}.\n\nThe mogu are plotting to steal three artifacts of power from the Vale.\n\nWe must retrieve the artifacts immediately and hide them for safekeeping.\n\nThe first artifact is the Battle Spear of the Thunder King.\n\nUpon emperor Lei Shen's death, the spear was placed in an ancient shrine to the northwest.\n\nBring the spear back to me.", progress = "It was said that the most powerful of ancient mogu could call the powers of the elements.\n\nThe Thunder King himself could channel the forces of lightning onto his spear.", completion = "Well done, {name}, although it pains me to lay my eyes upon that wretched spear.\n\nThis foul weapon murdered thousands of innocents.\n\nAs long as I live, the mogu shall never have possession of it again.", objectives = "Retrieve the Battle Spear of the Thunder King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30641] = { id = 30641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Helm of the Thunder King", description = "The second artifact of power is the Battle Helm of the Thunder King.\n\nEmperor Lei Shen wore the helm into every battle. It became so well-known that his enemies would flee at the mere sight of it.\n\nWhen the Emperor died, they placed the helm in the very bottom of the Guo-Lai Halls to the west, surrounded by thousands of terracotta soldiers.\n\nThus, they could look upon their leader and follow him into death.", progress = "History claims that Lei Shen feared no enemy except for one. And in the end, it was death that finally defeated him.", completion = "Thank you, {name}.\n\nWhile our soldiers fight the mogu on the battlefield, I work to strip away the power of their legends.\n\nIn time, Lei Shen shall be no more than the shadow of a memory.", objectives = "Retrieve the Battle Helm of the Thunder King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30642] = { id = 30642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Axe of the Thunder King", description = "The final artifact is the Thunder King's axe.\n\nLei Shen charged into battle with his spear in one hand, and his axe in the other.\n\nIt is said that he could throw his axe with brutal accuracy, and when it hit its target, it made a sound like crashing thunder.\n\nAfter his death, the axe was placed in a ceremonial chamber to the southwest.\n\nNeedless to say, we must not let it fall into the mogu's hands.", progress = "Did you find the axe?", completion = "Such modesty, {name}. I witnessed what you did to retrieve the axe. Well done.", objectives = "Retrieve the Battle Axe of the Thunder King.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30643] = { id = 30643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mogu's Message", description = "The battle against the mogu rages fiercely with neither side giving quarter.\n\nWe cannot hold our position forever. Something must be done to strike a blow at the mogu, a blow from which they cannot recover.\n\nGo check in with Zhi the Harmonious at The Silent Sanctuary. I wish to hear his thoughts on this matter.", completion = "Zhi the Harmonious and the defenders were slaughtered mercilessly.\n\nYour senses tingle. You realize that the Thunder King's treasures are gone!", objectives = "Speak to Zhi the Harmonious at The Silent Sanctuary in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30644] = { id = 30644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Comes to Pass", description = "You had better report back to the Golden Pagoda immediately.", completion = "What? Zhi the Harmonious... is dead? Oh...\n\nYou did very well, given the circumstances. I'm sure a lesser {class} would have succumbed to those assassins.\n\nThings are happening... so quickly. We must all keep ourselves together.", objectives = "Speak to Sun Tenderheart at the Golden Pagoda in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30645] = { id = 30645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of Three", description = "This is it, {name}. This is the end.\n\nIf we don't drive the mogu from the valley, they will seize the remnants of their ancient power and use it to break Pandaria to their will.\n\nBut our forces are few, and tired, and small. We bleed, while their warriors are made of stone.\n\n{name}, although all odds are against us, still I must ask you to go and help our forces slay the mogu invaders.\n\nI have prayed to the Celestials, begging their aid. I can only hope that they answer our call.", completion = "What? You have slain how many mogu?\n\nRemarkable! If we survive this, you must tell me everything that happened.", objectives = "Slay 100 mogu invaders at the Summer Fields in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30646] = { id = 30646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Power", description = "I never thought it would come to this!\n\nLeven went to face Warlord Zhao-Jin the Bloodletter at the top of the palace steps, but our reinforcements cannot get through!\n\nWe are the only ones who stand between him and the Vale's greatest... and most deadly... powers.\n\nPlease, {name}, you must find a way to stop him!", completion = "What you have accomplished today will live on in stories for ages to come.\n\nWith your help, we have saved the Vale from a terrible enemy.\n\nToday, we dealt a painful blow to the mogu. They will never stop their attempts to seize the Vale, but it will be a long time before they try a full scale attack again.", objectives = "Kill Warlord Zhao-Jin the Bloodletter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30647] = { id = 30647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Opened the Golden Valley" }
quests[30648] = { id = 30648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving On", description = "Your journey in this land has already proven most eventful, traveler. And mine, it appears, is destined to continue for a time.\n\nA chain of events began when your people arrived here, and while some of those happenings are traumatic to behold, I feel there must be a larger purpose behind your presence.\n\nFor now it is wisest that you leave this place and explore Pandaria's other regions.\n\nSpeak to me when you are ready to leave.", completion = "Be wise, traveler.\n\nProve to these inhabitants that there is more to your people than war and destruction.", objectives = "Speak to Fei and travel to Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30649] = { id = 30649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of Two Moons", description = "Look at this creature, traveler. Only moments after we arrived, this mogu assassin attacked with no warning.\n\nHis blade was intended for the leader of the Golden Lotus. It is very lucky indeed that we were here to stop the attack.\n\nSeeing this attempt on Zhi's life, I fear for the safety of those who have already entered the valley.\n\nThe caretakers are settling your people into the city to the northeast. Go and speak to the leaders. Make sure they are safe.", completion = "Good work, {name}. The city should be safe for now.", objectives = "Speak to Jaluu the Generous, Mokimo the Strong, Elder Liao, and Madam Vee Luo in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30650] = { id = 30650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Prisoners", description = "Look, I know the Alliance needs recruits, and there's just not enough of us here right now to make a fighting presence of this town.\n\nBut I know that the yaungol over at Fire Camp Ordo, to the northwest, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Alliance.\n\nWhat do you say, {name}?", completion = "Well, if it isn't our hero, {name}.\n\nI really wasn't sure we stood a fighting chance out here, you know?\n\nThese guys may be a little rough around the edges, but we'll be able to whip 'em into shape. And when we do, we'll have a real fighting chance at holding our own here in Kun-Lai.\n\nGood work.", objectives = "Free 8 Pandaren Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30651] = { id = 30651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels of Fun", description = "Oh, well now, let's have us some fun, <boyo/girly>!\n\nThose Ordo yaungol to the northwest have saved us the trouble o' havin' to make some bombs. They already have them there.\n\nLet's put their explosive barrels to good use and destroy their oil-pumpin' machines, shall we?", completion = "Ho ho, that were a fine sight to see. I knew I should have gone up there with ya, {name}!", objectives = "Use Explosive Barrels found in Fire Camp Ordo to destroy the West, South, and East Oil Rigs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30652] = { id = 30652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tents Channeling", description = "The yaungol of Fire Camp Ordo are a dire threat. I need you to head northwest and take out their leader.\n\nUnfortunately, his four subordinates are maintaining a fire barrier that prevents us from getting to him in the adjoining cave.\n\nTake them out and the shield will come down. You'll find them in their tents, channeling.", objectives = "Kill the Ordo Embercaller, Ordo Pyromancer, Ordo Firespeaker, and Ordo Blazecaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30653] = { id = 30653, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Does You No Good In The Keg", description = "I been thinkin'.\n\nWe got all this beer that Chen brewed, and we got all these people that you've gathered. We should bring the two together.\n\nThere's a bunch o' folks out there in the fields, riskin' their lives for Pandaria. You an' I should at least bring 'em a keg or two.\n\nThey might raise their mugs in victory. They might enjoy one last drink before gettin' skivvered by a mantid. Either way, I wouldn't want 'em to fight without a good brew in their belly.", objectives = "Bring beer to Zhu's Wardens, the Crane Wing Priests, the Shado-Pan, and the tauren settlers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30654] = { id = 30654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Guo-Lai Halls", description = "The mogu are up to something, I can feel it.\n\nThey've been sending scouts down into the Guo-Lai Halls.\n\nAccording to the caretakers, the Halls are home to ancient treasures of emperors past. Not only riches, but artifacts of great power.\n\nWe must prevent the mogu from accessing these treasures! Go down the ramp to the northwest and stop them!", completion = "It looks like you may have averted a great disaster, {name}.\n\nIf this mogu warlord seeks the treasures of the Guo-Lai Halls, we must do all that we can to stop him.", objectives = "Investigate the mogu presence in the Guo-Lai Halls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30655] = { id = 30655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaren Prisoners", description = "Look, I know the Horde needs recruits, and there's just not enough of us here right now to make a fighting presence of this town.\n\nBut I know that the yaungol over at Fire Camp Ordo, to the west, have taken many of my people as prisoners. And I also know that if you would be willing to rescue them from their captivity, they'd more than likely be willing to join the Horde.\n\nWhat do you say, {name}?", completion = "Well, it looks like we've got ourselves a little army, here, thanks to you.\n\nThey may not look like much yet, but a little Horde discipline and we'll have them in fighting shape in no time.\n\nBy the way, {name}... good work.", objectives = "Free 8 Pandaren Prisoners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30656] = { id = 30656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrels of Fun", description = "I love blowing stuff up. It's in my blood!\n\nThe yaungol to the west at Fire Camp Ordo have a ton of explosive barrels just lying around.\n\nI say we put them to good use and destroy their oil-pumpin' machines while having some fun!", progress = "Um, I don't think the job's done yet.", completion = "You can't tell me that wasn't fun, {name}! I knew I should have gone over there with you!", objectives = "Use Explosive Barrels found in Fire Camp Ordo to destroy the East, South, and West Oil Rigs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30657] = { id = 30657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Tents Channeling", description = "The yaungol of Fire Camp Ordo are the worst threat we're facing. I need you to head west and take out their leader.\n\nThe coward is hiding in a cave, which is protected by a fire shield cast by his four underlings.\n\nTake them out and the shield will come down. You'll find them in their tents, channeling.", objectives = "Kill the Ordo Embercaller, Ordo Pyromancer, Ordo Firespeaker, and Ordo Blazecaster.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30658] = { id = 30658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huff & Puff", description = "Have you heard of the prickly puffer fish {name}?  Of course you haven't, you're new around these parts!\n\nThey can be found in the sarjun depths, due west of here.  Take this fishing spear and see if you can bring me back of few of their poison tipped spines.", progress = "Careful with that spear, {name}.", completion = "Ahh, I see you recovered some spines {name}.  These will certainly work well on my spear tips!", objectives = "Use the Fishing Spear to kill 5 Prickly Puffer fish in Sarjun Depths and return with their spines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30660] = { id = 30660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ordo Warbringer", description = "<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo yaungol!>", completion = "You've done it, {name}! I'm in your debt!\n\nAgain!", objectives = "Kill Ordo Warbringer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30661] = { id = 30661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ordo Warbringer", description = "<The shield is down. Time to head into the cave and slay the Warbringer of the Ordo!>", completion = "Once again you've accomplished what no one else could.\n\nWas there any doubt?", objectives = "Kill the Ordo Warbringer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30662] = { id = 30662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ordo Warbringer", description = "You've taken the shield down at Fire Camp Ordo. Go back there before the shield goes up again.\n\nTime to head into the cave and slay their chief!", progress = "{name}, what are you doing here? The Ordo Warbringer isn't dead yet!", completion = "You've done it, {name}! I'm in your debt!\n\nAgain!", objectives = "Kill the Ordo Warbringer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30663] = { id = 30663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ordo Warbringer", description = "You've taken the shield down at Fire Camp Ordo. Get back over there before they get that shield up again.\n\nSlay the Warbringer of the Ordo!", completion = "Once again you've accomplished what no one else could.\n\nWas there any doubt?", objectives = "Kill the Ordo Warbringer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30665] = { id = 30665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Shado-Pan Fallback", description = "I sent for reinforcements from the Shado-Pan Monastery, but have heard nothing back. We have already lost the town.\n\nA few lucky villagers may have survived, but we are pinned down here.\n\nWe do not have time to entertain strangers. If you can fight, help my men defend this tower. If not, leave, for you will not survive long here.", progress = "Have you dealt with the yaungol yet?", completion = "You have bought us some time to breathe. We must not despair - instead, we must act.", objectives = "Kill 15 Sha-Infested Yaungol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30666] = { id = 30666, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sudden, Unexpected Crocolisk Aggression", description = "Normally, my day consists of catching fish, and then eating the fish I caught, followed by sleeping. Note that I did not include \"fight with a crocolisk\" in that list of activities.\n\nYou look like a handy {class}. Can you go get rid of some of these crocolisks, so I can get back to my regular routine? The crocolisks normally keep to themselves up at Kea Krak, to the northwest.", progress = "What would make the crocs attack like this?", completion = "Yesterday, we were fishing happily. Today, the crocs just started... tryin' to eat us.\n\nStrange.", objectives = "Slay 8 Mortbreath crocolisks at Kea Krak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30667] = { id = 30667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Particular Plumage", description = "When the crocs started attacking, they scared a bunch of the lories out of their nests, up in that island to our northwest.\n\nI can use those lories' feathers to make some specialized lures, which will come in handy if and when I get to stop defending my brethren from these reptiles.\n\nYou up for some feather hunting?", progress = "<A bead of sweat twinkles in the fur above Tony's brow.>", completion = "Thanks, {name}. You've made my day. I always hate to see such a prime feather-gathering opportunity go to waste.", objectives = "Obtain 6 Emerald Tailfeathers, 6 Crimson Tailfeathers, and 6 Dusky Tailfeathers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30668] = { id = 30668, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Build Your Own Raft", description = "<Jay looks off in the direction of Kea Krak.>\n\nHmm. They don't seem to be... calming down. We're going to have to try something different.\n\nYou'll need a raft. Go grab some wood planks and seaweed, and bring them over to me. I'll put something together for you.", progress = "You got the stuff? I'll build your raft, I just need materials.", completion = "<Jay deftly weaves the planks together into a surprisingly seaworthy-looking vessel, then tosses them down into water below.>", objectives = "Obtain 4 Spare Planks and some Tough Kelp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30669] = { id = 30669, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lorewalker on the Lake", description = "Your raft is down in the water below. Take it out to the middle of the lake, where you should find a woman. Her name is Ana  Wu.\n\nWhenever I have a question that I can't figure out on my own, I'll ask her. She should be able to tell us why these crocolisks won't stop attacking.", completion = "You appear troubled, child.\n\nHow can this Lorewalker serve you? What is it that you seek?", objectives = "Board your raft, then report to Wise Ana Wu in the middle of Nayeli Lagoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30670] = { id = 30670, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turnabout", description = "Our true enemies are the sha, not the yaungol.\n\nThe sha are emotion manifest. Destructive, yes. But undisciplined. Undisciplined force cannot last. The flood, in dispersion, loses its force. The wildfire burns its fuel.\n\nAnd, discipline and wisdom can turn their destructive energy against themselves.\n\nBring me the essences of the sha in the village, and I will explain further.", progress = "Have you harvested their essences?", completion = "Good. Now you will see how to defeat unbridled rage.\n\nI will craft these into a trap for Kobai, the leader of the yaungol. Though he will be snared, and we will defeat him, he is not our ultimate target...", objectives = "Collect 5 Blind Rage Essences from Blind Rages in Firebough Nook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30671] = { id = 30671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wisdom Has A Price", description = "<Ana listens to your story, and nods.>\n\nCrocolisks attacking? I know a story about that. And I will share it with you, but first... I grow hungry.\n\nShark meat should do the trick. You should find enough sharks in the water beneath us.", progress = "My hunger is great, {race}. I have been on this lagoon for several days, without food.", completion = "You've brought me more meat than I could ever hope to eat.\n\nNow, I suppose I owe you a story...", objectives = "Obtain 5 Shark Fillets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30672] = { id = 30672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance", description = "The story did not end happily. The Narsong crocolisk is no more.\n\nThis time, however, you may have a chance to change the ending.\n\nThe hozen to the south are overfishing these waters. With the fish gone, the crocolisks are hungry and desperate - and so they attack Marista.\n\nGo now, {race}! Stop those hozen from their reckless fishing!", completion = "<Jay listens to your account of the day's events.>\n\nI see. We'll keep an eye on the Ungas from here. And we'll do our best not to fish these waters too heavily, either. No doubt we're part of the problem, too.\n\nUntil next time, {name}.", objectives = "Slay 10 Unga Fish-Getters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30673] = { id = 30673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holed Up", description = "Thank the heavenly spirits for you, {class}! I don't know how much longer I could've lasted.\n\nThere are other Firebough Nook survivors, I'm sure of it. Will you help rescue them and get us to the safety of Shado-Pan Fallback?", objectives = "Rescue Jin Warmkeg, Ya Firebough, Old Lady Fung, and Sya Zhong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[30674] = { id = 30674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance Without Violence", description = "Some of the fish that the Unga hozen have gathered don't seem do be dead yet. There may still be time to throw them back into the water.", objectives = "Throw 6 Flailing Carp into Nayeli Lagoon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
